import{_ as a,C as r,o as i,c as l,j as e,a as o,E as s,a6 as n}from"./chunks/framework.CnPv4DE1.js";const g=JSON.parse('{"title":"如果你还年轻，就开始做这种新型生意","description":"","frontmatter":{"title":"如果你还年轻，就开始做这种新型生意","originalTitle":"If You’re Young, Start This New Type Of Business","date":"2025-03-22","originalUrl":"https://thedankoe.com/letters/if-youre-young-start-this-new-type-of-business/","minutes":16,"sourceHash":"decb5c937d44e1b7affcdd29e6ee7cb003d596bed994135aa74945e495a3190c","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/if-youre-young-start-this-new-type-of-business/"}]]},"headers":[],"relativePath":"letters/if-youre-young-start-this-new-type-of-business.md","filePath":"letters/if-youre-young-start-this-new-type-of-business.md"}'),h={name:"letters/if-youre-young-start-this-new-type-of-business.md"};function u(m,p,d,f,c,b){const t=r("ArticleMeta");return i(),l("div",null,[p[0]||(p[0]=e("h1",{id:"如果你还年轻-就开始做这种新型生意",tabindex:"-1"},[o("如果你还年轻，就开始做这种新型生意 "),e("a",{class:"header-anchor",href:"#如果你还年轻-就开始做这种新型生意","aria-label":'Permalink to "如果你还年轻，就开始做这种新型生意"'},"​")],-1)),s(t),p[1]||(p[1]=n('<p><a href="https://www.youtube.com/embed/O72qomfH39o?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>最好的商业模式，根本不是一种商业模式。</p><p>它是一种生活方式。</p><p>但大多数新手根本不在乎这个，甚至都没想过这一点。</p><p>他们想学“最好的”技能。</p><p>他们想多赚点钱，好辞掉工作。</p><p>他们想完全掌控自己的时间。</p><p>他们暗自想向朋友和家人证明自己。</p><p>人生的事业？</p><p>人生目的？</p><p>享受生活？</p><p>呵……这些事以后再说吧。</p><p>这也没什么问题。事实上，事情本来就该这么发展。</p><p>问题在于——<em>新手的盲目</em>。</p><p>大多数开始创业的人，显然并不知道该怎么创业。</p><p>所以他们开始盲目地寻找<em>可以做的生意</em>，而不是深入思考<em>自己想要怎样的生活方式，并规划出通往那种生活的路径。</em></p><p>他们带着那种曾在学校里表现优异、找到好工作时行之有效的思维，开始踏上创业之路，于是他们开始寻找一份新的“工作”来做，边做边学，就像还在学校里一样。</p><p>换句话说，他们试图用打工人的思维方式，而不是创业者的思维方式，去搭建一个事业。</p><p>他们学习怎么做自由职业。</p><p>他们学习怎么开一家社交媒体营销代理公司。</p><p>他们学习怎么搭建电商店铺，投放付费广告。</p><p>他们把自己重新塑造成了一个新的“朝九晚五”，又一次感到手头拮据、一天24小时被安排得死死的。但这一次，情况更糟。如果他们失去一个客户，或者不再每天工作12个小时，收入就会大幅下滑。</p><p>他们没有杠杆。他们感觉自己被困住了。</p><p>在这篇文章里，我不会给你一个把你框死在盒子里的静态商业模式。</p><p>相反，我会给你一份灵活的路线图，帮你追寻自己一生的事业。</p><p>这样一来，生意其实就是一个载体，通过它，你把自己喜欢做的事，分享给那些足够珍视它、愿意为之付费的人。</p><h2 id="创业的新方式" tabindex="-1">创业的新方式 <a class="header-anchor" href="#创业的新方式" aria-label="Permalink to &quot;创业的新方式&quot;">​</a></h2><p><strong>好的一面</strong>——有了互联网和社交媒体，商业已经发生了翻天覆地的改变，而且是往好的方向变。这给了单人创业者和小团队更大的力量，而这种力量在互联网和社交媒体之外，只会变得更加强大。</p><p><strong>坏的一面</strong>——你能找到的几乎所有针对新手的创业信息，依然被旧的商业范式所主宰。</p><p>旧的做事方式是：</p><ul><li>选一个细分领域</li><li>选一个客户画像</li><li>选一项技能</li><li>选一种商业模式</li></ul><p>95%的情况下，人们选择的都是别人告诉他们“最赚钱”的那个东西。</p><p>结果就是，他们选了一个自己毫无经验的细分领域，去服务自己根本不在乎的人，去学一项与自己兴趣毫不相干的技能，选了一种听起来最炫或者看起来最简单的商业模式。</p><p>想赚钱本身没什么错。但如果你认为不牺牲那些让生活变好的东西就赚不到钱，那就纯属愚蠢了。</p><p>什么让生活变好？</p><p><em>把注意力投入到你认为重要且有意义的事情上。</em></p><p>问题是，“你认为重要且有意义的东西”会随着你心智的发展而演变。所以，如果你选了一种永远一成不变的商业模式，那你就是在给自己安排一场悲惨的人生。</p><p>在旧的经商方式里，金钱被摆在第一位——也是<em>唯一</em>的理由，你把注意力投入到别人说服你<em>相信</em>重要的人、项目和技能上。</p><p>新的经商方式，是把你<em>理想的生活</em>摆在第一位，但不是唯一的理由。</p><p>在这种新方式里，你不是去<em>选择</em>一个细分领域、一项技能或一种模式，而是：</p><ul><li>成为那个细分领域本身</li><li>帮助过去的自己</li><li>解决自己的问题</li><li>追随杠杆最高的路径，这意味着随着你的进步，商业“模式”也会不断变化</li></ul><p>你不需要“工作与生活的平衡”，因为工作和生活会合而为一。你会因为做自己而获得报酬。这本来就该是这样。</p><p>当你意识到这一直是一个选项，而你之所以被学校和工作所吸引，其实是因为你的心智基于你过去人生条件被塑造成了接受某些价值观，你就再也无法忽视这一点了。所以，不用谢我。享受这段旅程吧。</p><p>这条路是一个过程：在其中你不断发展自己，分享你所积累的价值，并通过把你自己曾经的问题打包成解决方案、分发给曾经和你处境相似的人，来维系你理想的生活。</p><p>因此，这条路只适合那些珍视提升自己心智、身体、技能、财务和人际关系的人。这是一种生活方式，如果你的生活方式是懒散、平庸和图快速见效，那你走不通这条路——说实话，换成任何其他形式的生意，你大概也走不通。</p><h2 id="杠杆最高的路径" tabindex="-1">杠杆最高的路径 <a class="header-anchor" href="#杠杆最高的路径" aria-label="Permalink to &quot;杠杆最高的路径&quot;">​</a></h2><p>如果你想让自己本身变成生意，或者靠做自己想做的事赚钱，你需要以下几点：</p><ol><li>从新手到高手的成长路径</li><li>一种能把人吸引到你正在积累的价值上的方式</li><li>能随着你的成长而进化的产品或服务</li></ol><p>用老旧过时的商业模式，你会选择一种模式——比如电商——它附带一堆前提条件，大多数新手根本应付不了。</p><p>你需要几千美元去投入库存。你需要学习营销、销售、广告等等……但你早已埋下了一个定时炸弹。大多数生意失败，是因为没钱支撑他们在试错中把生意维持下去。如果第一次或第二次尝试就失败了，你就彻底完了。</p><p>你很少能立刻开始赚钱。相反，你立刻开始花钱，然后希望能在被迫放弃之前把它做起来。</p><p>而在新的经商方式里，情况正好相反。</p><p>你不需要任何经验，因为这份事业本身<em>就是你获得经验的方式。</em></p><p>你使用免费或廉价的技术和软件来积累受众，并做出你的第一个产品或服务。</p><p>你把失败的可能性（由于缺钱或缺经验）降到了<em>零。</em> 你在这条路上失败的唯一理由，就是你过早放弃、无法坚持、无法迭代、拒绝学习……或者，你干脆认定自己当初想逃离的生活“也没那么糟”——因为你的大脑开始跟你玩心理游戏了。</p><p>考虑到这些限制条件（新手、缺钱、零经验），我们可以得出几个起点：</p><h3 id="_1-打造受众" tabindex="-1">1）打造受众 <a class="header-anchor" href="#_1-打造受众" aria-label="Permalink to &quot;1）打造受众&quot;">​</a></h3><p>如果你没钱做付费广告、赞助或者网红营销，你最好的选择就是打造自己的受众。</p><p>其实，我认为每一个新手都应该打造受众，无论如何。</p><p>为什么？</p><p>因为它能免费地、通过实践教会你在任何商业形式中做好所需要的技能：营销、说服、媒体、写作、设计、心理学、人性洞察。</p><p>更进一步说，这就是当下谈论和传授你兴趣所在的现代方式。你不仅能学到营销之类技能中必要的部分，还能借助费曼技巧<em>更快</em>地学到你感兴趣的东西。你发布的每一条内容，都会暴露出你知识上的空白，让你能更快地掌握那个主题。</p><p>打造受众，就像是把个人成长和你的兴趣结合在一起，让你能靠这件事养活自己一生。</p><p>没错，你也可以去Reddit论坛发帖，或者做网站SEO来获客，但我们要走的是<em>杠杆最高的路径。</em></p><p>当你打造受众时，你会<em>留住</em>这些受众，尤其是当你有一份人们可以订阅的邮件列表。</p><p>用付费广告，你花钱让某个社交平台把你的内容展示给一个不属于你的受众，而那些人根本不知道你是谁。</p><p>而打造受众，你就不必那么担心营销或销售，因为这些技能本质上都是关于<em>信任</em>的。如果你每天都给一群不断增长的受众发布内容，你的信任度会随着时间自然而然地累积起来。</p><p>如果你需要一个带模板的起点来做这一切，可以看看<a href="https://stan.store/thedankoe/p/the-oneperson-business-launchpad--your-first-5k" target="_blank" rel="noreferrer">一人企业启动包</a>。没有花招，只有基础内容，适合想把一切都集中到一处的人。</p><h3 id="_2-不断进化的产品与服务" tabindex="-1">2）不断进化的产品与服务 <a class="header-anchor" href="#_2-不断进化的产品与服务" aria-label="Permalink to &quot;2）不断进化的产品与服务&quot;">​</a></h3><p>当你的受众还很小的时候，你需要留意这一点。</p><p>你需要做一些数学计算。</p><p>如果你打算卖一本19美元的实体书或规划本，你会需要<em>大量</em>的客户，才能替代你目前的收入。</p><p>作为一个独立程序员，构建一款App或软件，然后贴上每月10到20美元的价签，也是同样的道理。</p><p>这不代表这条路走不通。事实上，我推荐学习能力强的人走这条路。</p><p>配合正确的社交媒体策略，你的帖子从一开始就可能表现得很好，这样你就能把低价产品做起来。</p><p>但对大多数人来说，这种情况不会发生。</p><p>更好的方式是从自由职业、教练或咨询服务开始。</p><p>很多人对此很抵触，因为自由职业者和教练实在太多了（实际上并没有那么多，只是你还没入局，所以产生了误判），于是他们转而选择更高阶的商业模式，结果照样失败。</p><p>做这类服务，你只需要3到5个客户，每月收费1000到3000美元（取决于你的报价），就能获得一份不错的收入。</p><p>实现这一点有很多方式，但在打造受众的过程中：</p><ul><li>你可以给那些与你的内容互动过的人发消息，介绍你的服务（这比冷开发要好，因为对方已经知道你是谁了）。</li><li>你可以在个人简介和高表现内容里附上一份问卷链接，让感兴趣与你合作的人填写，然后再私信跟进，促成合作。</li></ul><p>记住我们的两个起始选项：</p><ol><li>一个数字产品，比如模板、指南或电子书</li><li>一份自由职业、教练或咨询服务</li></ol><p>对第一种情况，你需要非常擅长用内容引流。</p><p>对第二种情况，你需要销售和外联方面的知识，才能促成这些合作。</p><p>两者都是可行的起点，但要明白这是一个学习过程。你一边学习，<em>一边</em>尝试赚取收入，而且至少你在同时打造着一份受众，这份受众会让一切慢慢变得越来越容易。</p><p>接下来，当你把其中一种方式做成功后，你就可以把那个产品或服务<em>进化</em>成杠杆更高的东西。</p><p>一份自由职业服务，可以进化成一门传授你技能或你的方法体系的数字产品。</p><p>一个数字产品，可以进化成软件或实体产品（这时你已经有了受众和知识，能让电商生意一次就做成功，而不是反过来先做电商再费力搭建受众）。</p><p>你明白这为什么强大了吗？用这种模式，你依然可以搭建任何你想要的生意类型，只是你<em>起步</em>的方式，让你在还是新手的时候也能做到。</p><p>随着每一次进化，你花在完成工作上的时间会越来越少，能赚到的钱会越来越多，而你也拥有了足够庄大的受众来推动整个过程。</p><p>客户型的工作——比如自由职业或做教练——意味着你只有那么多时间，也只能接那么多客户，也就意味着，除非你雇一个团队，你的收入终究会到达某个上限。</p><p>产品通常可以在你睡觉时也持续销售，如果你有受众来为它们提供动力，你可以做得相当不错，并对自己的生活拥有更多的掌控权。</p><p>到那个阶段，你应该已经有足够的钱去享受生活，或者更进一步，投资开创一家更大的公司，比如软件创业公司或者更重度的业务。</p><h3 id="_3-t型内容" tabindex="-1">3）T型内容 <a class="header-anchor" href="#_3-t型内容" aria-label="Permalink to &quot;3）T型内容&quot;">​</a></h3><p>如果你听到“内容”或“内容创作者”这个词会感到别扭，别担心，我也一样。</p><p>我想让你明白的是，吸引客户关注你的作品，主要有三种方式：媒体、口碑，以及直接触达。</p><p>直接触达在刚开始做一些像服务类的东西时很有用，但它的杠杆很低，而且很慢。</p><p>而且如果没有媒体在先，你大概也得不到口碑，所以我们显然要聚焦在媒体上。</p><p>付费广告是媒体。SEO是媒体。广告牌和电台也是（过时的）媒体。</p><p>任何你为了吸引客户而<em>制作</em>出来的营销材料都是媒体。但当然，我们是在建立受众。</p><p>所以，如果这样想有帮助的话，把“内容”当成媒体的同义词就好，因为它本来就是。</p><p>你不需要把自己定位成一个内容创作者，才能去执行这件决定你事业大部分成败的单一事项：创作内容。</p><p>但作为新手，你该如何开始写内容呢？</p><p>80%的内容围绕你计划打造产品或服务的那个主题。</p><p>20%的内容基于其他兴趣或观点，用来试探你的受众喜欢什么。</p><p>“T型。”这是Valve用来形容那些在很多方面都不错、但在某一件事上特别精通的员工的术语。深耕你的主要专长，辅以你的其他兴趣。</p><p>但记住，在社交媒体上，你是被推给那些根本不认识你、而且很可能对你谈论的话题还是个新手的随机人群（是的，即使你在卖自由职业服务，你要为之工作的那个人也是新手，否则他们不会雇你）。</p><p>所以，避免搞得太技术化或太耍聪明。</p><p>专注于教育和说服人们，让他们明白你的主题为什么重要。</p><p>随着你的受众增长、产品演变，你的内容也会随之演变。</p><p>这里面有很多细微之处，所以我建议你要么去入手<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>，要么等我在另一篇信件里再深入讲这个话题。</p><h2 id="但我该如何开始" tabindex="-1">但我该如何开始？ <a class="header-anchor" href="#但我该如何开始" aria-label="Permalink to &quot;但我该如何开始？&quot;">​</a></h2><p>让我们先把一件事说清楚：</p><p>没有人能告诉你该如何打造一家企业。</p><p>他们只能告诉你他们自己是怎么打造出来的。</p><p>没有人能教你品牌、内容创作、写作、营销、产品，或者其中任何一样东西。他们只能分享在他们所处的情境下、用他们那样的头脑，对他们有效的流程。</p><p>问题是，你不在他们那样的情境中。</p><p>你也接触不到他们的头脑。</p><p>这一点适用于你生活中的任何事：</p><p>你可以研究别人那些无比宝贵的流程，但你永远逃不开这种需要：通过实验、坚持和迭代，把那个流程变成你自己的。</p><p>所以，你可以把这些当作一个起点，但它们仅仅是起点。</p><p>这些指导原则是为了帮你理清思路。</p><p>它们不是法律。</p><p>先学会规则，然后打破它们，这样你才不会既成为一个克隆体，又是个失败者。</p><h3 id="_1-聪明地模仿" tabindex="-1">1）聪明地模仿 <a class="header-anchor" href="#_1-聪明地模仿" aria-label="Permalink to &quot;1）聪明地模仿&quot;">​</a></h3><p>你不需要一整本资料书才能建立起你的账号资料、写出爆款内容、并靠销售一款产品赚到数百万。</p><p>你只需要两只眼睛，连着一个能勉强运转的大脑。</p><p>观察和实验是最好的老师，而你其实正淹没在教育资源之中。你每天都在看社交媒体简介、品牌、内容和营销，但你是以消费者的视角在看。</p><p>一旦你切换到创作者的视角，你信息流上的一切都会变成灵感，你可以像艺术家一样把它们“偷”过来。</p><p>简而言之，如果你想学会做任何事：</p><ul><li>保存3-5个灵感来源（品牌、内容、产品）</li><li>拆解每一个的结构和特征</li><li>拿其中一个小的部分出来试试</li><li>然后再拿一个，再一个，再一个</li><li>随着推进，用课程、视频或其他教育资源做补充（这样你才能理解你为什么在做你正在做的事）</li></ul><p>举个例子，如果你想写一份通讯，并以我的通讯为灵感，你可以先从拆解结构开始：</p><ul><li>开头讲我如何看待一个话题，揭示大多数人是怎么想的，然后深挖为什么那是个问题</li><li>一段用来展示做某件事的“旧方式”和“新方式”</li><li>一段对整个流程的全局性概览</li><li>最后一段是给新手的可执行步骤</li></ul><p>你可以拿这个结构，围绕一个完全不同的主题列出一份通讯大纲，让你的第一篇文章就比99%的人写得更好。</p><p><strong>那打造品牌呢？</strong></p><p>看看你那3-5个灵感来源，找出它们之间的共同模式。</p><p><strong>那写内容呢？</strong></p><p>找一个已经被验证过、互动很好的想法，拆解出是什么让它表现出色，然后把它重写一遍。</p><p>学任何东西都可以这么简单（不代表容易）。</p><p>当你建立起账号资料、写出你的第一批内容、打造你的第一款产品时，就照这个方法做。</p><p>研究表现好的内容。研究表现好的品牌。研究表现好的产品。每次写作、设计、构建或销售时，都从每一个当中取一点，你就会做得不错。</p><h3 id="_2-学会直接反应营销-然后忘掉它" tabindex="-1">2）学会直接反应营销，然后忘掉它 <a class="header-anchor" href="#_2-学会直接反应营销-然后忘掉它" aria-label="Permalink to &quot;2）学会直接反应营销，然后忘掉它&quot;">​</a></h3><p>直接反应营销，是骗子和油腻二手车推销员的代言词。</p><p>它催生了Clickfunnels、倒计时器、虚假稀缺感的时代，以及现在会让人在脑中拉响警报的所有那些东西——尽管在那个时期它曾极度赚钱。</p><p>它今天仍然存在于TikTok商店、代发货、消费类App下载中——主要是短视频内容和销售页。有些人做得比另一些人体面一些。</p><p>简单来说，直接反应营销，或者说广告本身，就是学习如何抓住注意力、引导注意力，并让读者采取行动或“转化”。</p><p>很多人现在干脆把它叫做“文案写作”，并把它标榜为“赚钱要学的最厉害的技能”。他们说得也不算错。Hormozi就是靠这个成名的。</p><p>虽然这项技能<em>可能</em>很油腻、不道德，但它不必如此。</p><p>在我看来，<em>这是在一个实用的地方，把心理学原理、人性和注意力全都集齐的最佳方式。</em></p><p>直接反应营销的陷阱在于，只专注于快速捞钱，而忽视了长期的品牌建设。当你把两者结合起来，并且不为了短期现金而牺牲长期品牌时，魔法就会发生。</p><p>如果我今天要重新学习这些基础，我会：</p><ul><li>读德鲁·埃里克·惠特曼（Drew Eric Whitman）的《Ca$hvertising》</li><li>读罗伯特·西奥迪尼（Robert Cialdini）的《影响力》（Influence）</li><li>我没读过，但听说拉塞尔·布伦森（Russel Brunson）的《Traffic Secrets》和《Expert Secrets》评价很高（尽管他现在在公众眼中的形象已经不太好了）</li><li>听5-10个YouTube视频和播客</li><li>写通讯、落地页和社交帖子，练习你学到的东西</li></ul><p>很多文案人不同意我说的读这些东西（他们有别的推荐），但这些就是我读过的，而且帮了我很多。我不是一个专业的文案写手，但我为自己做得相当不错。</p><p>这一点我再怎么强调都不够：</p><p>专注于原理，而不是战术，你就会没问题。</p><h3 id="_3-确立你是谁、你在做什么、以及你为什么在这里" tabindex="-1">3）确立你是谁、你在做什么、以及你为什么在这里 <a class="header-anchor" href="#_3-确立你是谁、你在做什么、以及你为什么在这里" aria-label="Permalink to &quot;3）确立你是谁、你在做什么、以及你为什么在这里&quot;">​</a></h3><p>再说一次，人们犯的最大的一个错误，就是认为社交媒体是某种彩票。</p><p>他们不明白，社交媒体是一种可以学习的技能——就像其他任何事一样——所以他们进场时想的是，随便写点旧帖子，然后祈祷我们的主和救世主——算法——会在一夜之间让他们暴富成名。</p><p>别这样。</p><p>现实是，当你刚开始时，绝对没有人知道你，也没有人在乎你。</p><p>你旅程的头6-12个月，应该用来证明你有价值可以提供。</p><p>你要怎么做到这一点？</p><ul><li><strong>免费下载资源</strong> — 制作一份全面的免费下载资源，教授你主要话题或兴趣领域的基础知识。不像社交内容一天之后就消失，免费下载资源可以放在你的个人简介里链接，并反复推广。<a href="https://join.stan.store/thedankoe" target="_blank" rel="noreferrer">你可以在Stan上托管你的免费下载资源，为你的个人简介创建链接，并构建产品或服务。</a></li><li><strong>把它延伸成一款产品或服务</strong> — 人们以为数字产品会让他们变成“卖了良心”的人，实际情况恰恰相反。大多数创作者失败的原因，是他们没有一款人们能买、并能改变他们生活到成为忠实粉丝的产品。你的内容能起的作用是有限的。把你的产品链接放进你的免费下载资源里，让它带来你的头几块钱。</li><li><strong>撰写基石内容</strong> — 你80%的内容应该围绕你的故事、你主要话题的基础知识、可执行且权威的建议、你一天中都做些什么，以及为什么你觉得这些都很重要。</li><li><strong>把自己嵌入一个“部落”</strong> — 当我想加入社交媒体上一个新的“空间”或细分领域时，我会列出5-10个人的名单，开始让自己被他们注意到。我评论他们的帖子，加入他们的社群，分享他们的内容，私信他们展开对话。随着时间推移，那个社群会越来越了解我，越来越多地看到我的脸。<em>这可以说是最重要的一步。</em></li><li><strong>写高质量的评论</strong> — 请原谅我用词直接，但天呐，人们真是完全不明白这意味着什么，无论这一点在你收到的任何社交媒体建议中被重复了多少次。打开任何帖子的评论区，简直是一堆垂圾。而在这里脱颖而出其实是世界上最简单的事。“很有见地”不是一个好评论，也不会让别人开始关心你。AI生成的回复很明显，只会让你被拉黑。只需要在别人的帖子下用“我记得有一次……”开头，然后讲一讲你生活中的某个时刻，那个时刻和他们帖子的主题相关。这会让更多人对你产生好奇。</li></ul><p>是的，这需要花功夫。这是一项事业。它不会很快。它需要时间。这些都应该显而易见。你显然要先建立起一个信息基线，让人们能有东西可以真正咬住去消化，然后才会信任你。发几条社交帖子是不够的。</p><p>这封信就到这里。</p><p>我会在以后的信中对其中一些内容做进一步展开。</p><p>现在，如果你想在自己的学习上做投资，最好的去处是<a href="https://stan.store/thedankoe/p/the-oneperson-business-launchpad--your-first-5k" target="_blank" rel="noreferrer">OPBL</a>，或者<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>。</p><hr><p><a href="/en/letters/if-youre-young-start-this-new-type-of-business">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',170))])}const k=a(h,[["render",u]]);export{g as __pageData,k as default};
